"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["761"],{9866(e,t,a){a.r(t),a.d(t,{metadata:()=>o,default:()=>c,frontMatter:()=>s,contentTitle:()=>r,toc:()=>h,assets:()=>d});var o=JSON.parse('{"id":"reference/dashboard","title":"Dashboard","description":"connectivity \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/dashboard.md","sourceDirName":"reference","slug":"/reference/dashboard","permalink":"/personal-av-docs/docs/reference/dashboard","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/dashboard.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Dashboard","sidebar_label":"Dashboard","sidebar_position":99,"edition":"connectivity","source":"https://doc.airvantage.net/connectivity/reference/dashboard","format":"md"}}'),n=a(4848),i=a(8453);let s={title:"Dashboard",sidebar_label:"Dashboard",sidebar_position:99,edition:"connectivity",source:"https://doc.airvantage.net/connectivity/reference/dashboard",format:"md"},r,d={},h=[];function l(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsxs)(t.p,{children:[":::note Edition\n",(0,n.jsx)(t.strong,{children:"connectivity"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,n.jsx)(t.a,{href:"https://doc.airvantage.net/connectivity/reference/dashboard",children:"Original page"}),".\n:::"]}),"\n",(0,n.jsx)(t.p,{children:"Dashboard\nMonitor\nConfigure\nAPI, Connectors & Other Services\nWeb Services API\nCloud Connectors\nCloud Connectors Format\nUSSD Gateway\nMore\nProduct page\nSearching...\nMatching results\nDashboard\nInitializing Table Of Contents...\nYour dashboards\nAirVantage provides dashboards that are available troughout the product to provide greater insight into your systems.\nThe Dashboards are configurable so you can get a quick look at the information that is the most important, in the correct context in your use of AirVantage.\nThe start Page\nThis main dashboard can display information about the fleet or about a single system you want to monitor closely. It provides the greatest variety of options to configure\nYou can always access to the dashboard clicking on the AirVantage logo at the top left.\nThe Systems Dashboard\nThis page displays basic information about your systems at a glance.\nYou can access it from Monitor > Systems.\nThe System Detail View\nThis page allows you to display information about the selected system, and provides system-specific widgets.\nYou can access it from the previous dashboard and click on a system in the table.\nOrganize your dashboards\nYou can create multiple dashboards for the start page (fleet dashboard) and the system\u2019s details page. The Monitor Systems view can just have a single dashboard.\nAll accounts come configured with a dashboard that provide the most commonly used widgets, in a layout that is designed for most users.\nAll dashboards are created as private (only available to you) and you have control to change the default dashboard to be displayed for a System or in the start page for all your devices. This enables you to:\nDesign one or more dashboards to address specific use cases\nUse dashboard configurations temporarily or for more long-term requirements\nBuild multiple views of your fleet for a greater visibility\nTo manage your dashboards, you can:\nCreate a new empty dashboard\nCreate a new dashboard from a current one: Clone an existing dashboard and modify it\nSet the default dashboard to be one you have created or use the initial dashboard depending on your requirement\nDelete a dashboard when you don\u2019t need it anymore. If this is the current default dashboard, the new default one returns to the initial dashboard.\nShare your dashboards with your team and partners\nThe list of dashboards can be accessed through the combo list on the top right of the dashboards. You access to the private and public repositories:\nInitial dashboard:\nThe initial dashboard can not be modified and this dashboard will be always available as is. If you want to modify it, clone it and edit the newly created dashboard. This dashboard is nammed\nInitial Dashboard\n.\nPrivate Dashboards:\nBy default, your dashboards are private dashboards. This means that you, and only you, can view, delete or update your dashboards. The first one shown when you display the page is the default dashboard. The default dashboard is identified with a 4 squares icon on the left.\nPublic Dashboards:\nYou can share a dashboard to other user in your company (in a public repository). The dashboard is in read-only for all the users but the Administrators. See\nHow to share a dashboard\nfor more information. A public dashboard is identified with an eye on the left.\nFinally, you can transfer a dashboard to a partner. The dashboard will be copied to the new company as a public dashboard. If you modify the dashboard, the transfered dashboard will not be changed. See\nHow to transfer a dashboard to a partner\nfor more information.\nUse your dashboards in full screen mode with auto refresh\nAuto refresh mode\nThe AirVantage dashboards use the available data when the dashboard is displayed so you can analyze your fleet or system status but by default but the data are not updated. If you want an up-to-date status displayed in the dashboard, you can use the auto refresh mode which updates the data in each widget at given period.\nThis period is 1 minute at the minimum and can be configured according to your use case and device communication policy.\n24h after the login, the user must login again for security reasons.\nFull screen mode\nYou may want users to view a dashboard without all of the navigation toolbars, menus, and panels of your browser. Hiding the navigation information:\nFocuses attention on the data itself\nAllows for easier analysis of the data by maximizing the number of widgets shown at the same time\nAllows to share your metrics by casting your dashboard to a TV in a control center by using auto refresh and full screen modes all together.\nDesign your dashboard\nTo change the dashboard layout, you need to switch into \u2018Edit mode\u2019.\nOnce in Edit mode, you can easily:\nChange the name and the description which will be used in the dashboard list\nAdd or remove widgets\nResize existing widgets\nMove widgets around to have the most important ones on the top and create a layout that works for you\nAdd widgets\nOnce in \u2018Edit mode\u2019, use the quick search drop-down box listing widgets by name, or select from the well-known widget gallery by clicking on the magnifying glass button. The widget will be added to the bottom of your dashboard. You can then move it where required, and do any widget specific configuration that is required.\nOnce you are satisfied with the look and feel of the modified dashboard, click on\nSave\nbutton to validate your changes.\nDrag and Drop\nYou can position the widgets as you wish to obtain the desired dashboard layout.\nJust drag a widget and drop it on an existing widget slot. Widgets are then automatically switched.\nResize\nResize widgets as desired to get best visual effect or to best organize your dashboard.\nRemove widgets\nRemove widgets you don\u2019t need.\nDuplicate a widget\nClick on\nDuplicate\nin the top right widget\u2019s menu. The new widget will be added to the right of the current widget.\nCommon Configuration for all the widgets\nTyping # will enable you to include variables inside your label like:\n#sourceName\n: Name of the current datasource (company name if datasource is fleet, system name if you selected a system)\n#dataAggregation\n: Type of aggregation (mean, sum, \u2026)\n#dataInterval\n: Time of aggregation (monthly, daily, hourly)\nWidgets have a wide range of configuration capabilities. Some are simple and require no configuration; some are more complex and require more information.\nUse widgets to filter entities\nWidgets can be used to filter entities.\nIn the example below the systems with Good RSSI level are filtered clicking on the slice\nGood\nof the\nRSSI\nwidget. All the pie charts offer this capability:\nCellular Band Widget\nThe Cellular Band widget is available in the ALMS offer for multi-radio routers running AirLink OS. It is not supported on ALEOS devices.\nThe widget shows the current number and distribution (by percentage) of systems using each band. The data displayed is based on the system\u2019s last recorded Band value.\nYou can select the radio interface (Primary, INT/XP1, XP/XP2) for which to display band data.\nThe 6 most represented bands are displayed, with the rest of the bands grouped under \u201COther\u201D. However, if the \u201COther\u201D category only contains 1 band datapoint, then the band will show as its own category instead of \u201COther\u201D.\nYou can view the \u201COther\u201D bands by moving the pointer over the relevant segment.\nTime Display\nDate and time is displayed in\nrelative time\n(for instance\n10 minutes ago\n, not\nFebruary 13th 2019 2:05 PM\n) along with the full UTC Date and Time displayed in a tooltip when hovering over it.\nTime display\xa0for each range is outlined in the table below:\nRange\nKey\nSample Output\n0 to 45 seconds\ns\nseconds ago\n45 to 90 seconds\nm\na minute ago\n90 seconds to 45 minutes\nmm\n2 minutes ago \u2026 45 minutes ago\n45 to 90 minutes\nh\nan hour ago\n90 minutes to 22 hours\nhh\n2 hours ago \u2026 22 hours ago\n22 to 36 hours\nd\na day ago\n36 hours to 25 days\ndd\n2 days ago \u2026 25 days ago\n25 to 45 days\nM\na month ago\n45 to 345 days\nMM\n2 months ago \u2026 11 months ago\n345 to 547 days (1.5 years)\ny\na year ago\n548 days+\nyy\n2 years ago \u2026 20 years ago\nTracker Widget\nTracker shows you the near real-time location of your routers on an interactive map. It is especially useful for monitoring a fleet of vehicles, and can display up to 20,000 systems concurrently.\nIt includes filtering and clustering features to make it easy to look at the whole fleet, or to focus on individual vehicles.\nSee\nHow to Use the Tracker Widget\nand\nConfiguring the router for the Tracker Widget\nfor more information.\nData Widgets\nThis is a subset of available widgets. A lot of pre-defined widgets are available, which you can use without any configuration.\nSingle Value Chart\nA\nSingle Value Chart\nshows a single data value. You can apply rules, to adapt the content.\nCombo Chart\nA\nCombo Chart\nshows data in a graph: bar (stacked or not), line or with both.\nTable Chart\nA\nTable Chart\nshows until 4 data values.\nData History Table\nA\nData History Table\nshows the data value history in a table. Each data are displayed in a row. You can select the period to display.\nData List\nA\nData List\nshows the data value history in a list. Each value is displayed in a row. You can select the number of row (default is 20, maximum is 50).\nGauge Charts\nFor all the type of gauge, you can configure the minimum, the maximum level and the colors for each area.\nAngular Gauge\nAn\nAngular Gauge\ndisplays a gradient color which is displayed only from the lower limit until the current limit.\nSolid Gauge\nA\nSolid Gauge\ndisplays a gauge with always displayed color areas so that you can easily visualize the range your reported data is in. You can configure the number of marks and the associated labels.\nVU Meter\nA\nVU Meter\nis an analogic-like meter. The 3 areas are always displayed.\nThermometer\nA\nThermometer\nis a vertical gauge. The color highlights the zone corresponding to the value. You can configure the number of marks and the associated labels.\nTank\nLike the Thermometer, the\nTank\nis a vertical gauge. The color highlights the zone corresponding to the value. You can configure the number of marks and the associated labels.\nOther Widgets\nCommand Widget\nThis widget displays buttons to send commands to the device. Parameters can be configured. If any mandatory parameter is missing, the user has to define it right after clicking the button.\nText Widget\nAdd more context (like pictures, formatted text, links) about your systems. Add references to your corporate technical documentation about your machines, display your logo\u2026\nMain Life Cycle Dates Widget\nThis widget provides insight into the state of your System in ALMS. The widget provides the following information on four dates:\nCreation Date\n: The date that the System was created in ALMS. This is typically the date that the router was registered into ALMS.\nActivation Date\n: The date that the System was activated on its offer in ALMS. In most cases, the Creation Date and Activation Date are the same date (generally separated by a few seconds), as the default behavior is to activate upon registration. It is possible to delay activation for up to 60 days, so these dates may be different.\nLast State Change Date\n: This date reflects the most recent state change to the device. For most ALMS users, this date is generally close to the Creation Date or Activation Date for the first year of the System\u2019s life. It could be different if an older device (one not eligible for AirLink Services) was registered, was then suspended and reactivated at a later date, once services were renewed. Generally, this date will remain constant throughout the life of an AirLink router.\nEnd of Engagement\n: This date indicates the end of the service contract period. In this example, the AirLink Complete service for the AirLink XR60 was valid for 1 year, showing that the end of the original engagement period will expire on October 16, 2024. You can also refer to the Services dates in the\nMonitor > Systems\ntable for this information.\nAlert Widgets\nAlert Status Widget\nThis widget shows a textual and graphical view of the current state of an alert. It\u2019s up to you to define what to show based on the state of the alert.\nAlert History Widget\nThis widget shows the recent history of the system\u2019s alerts on a graphical view. You can browse the alert history within a given period, zoom on a given date and hide alerts in the graph by clicking on the bottom legend.\nThis widget is only available in the System Detail dashboard.\nNote the color code for each rule is the same as in the\nAlert List Widget\n.\nAlert List Widget\nThis widget shows the alerts as a list. It is available both for the fleet or for a specific system. You can filter the alerts to be shown by rule or limit the display to alerts still ongoing. From this widget, you can:\nclick on the system name to show all alerts for a system (available only for fleet version in the start page dashboard),\nclick on the alert name to show all systems with the same alert,\nclick on a link to go to the system details in order to investigate deeper,\nshow a popup with the alert duration when hovering over the start or end date of the alert.\nHow-Tos\nThis section provides you with helpful procedures for common tasks.\nHow to customize the data display in a single value widget?\nHow to display your data in a combo chart?\nHow to share a dashboard?\nHow to transfer a dashboard to a partner?"})]})}function c(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},8453(e,t,a){a.d(t,{R:()=>s,x:()=>r});var o=a(6540);let n={},i=o.createContext(n);function s(e){let t=o.useContext(i);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:s(e.components),o.createElement(i.Provider,{value:t},e.children)}}}]);